package jp.wakeguard.alarm;
import android.appwidget.*;import android.content.*;import android.widget.RemoteViews;import java.time.*;import java.time.format.DateTimeFormatter;
public class TodayWidgetProvider extends AppWidgetProvider{
 static void update(Context c,AppWidgetManager m,int id){RemoteViews r=new RemoteViews(c.getPackageName(),R.layout.widget_today);r.setTextViewText(R.id.today_date,LocalDate.now().format(DateTimeFormatter.ofPattern(I18n.datePattern(c,"next"),I18n.locale(c))));long at=AlarmScheduler.nextTriggerMillis(c);r.setTextViewText(R.id.today_alarm,at>0?I18n.tr(c,"次のアラーム")+"  "+Instant.ofEpochMilli(at).atZone(ZoneId.systemDefault()).format(DateTimeFormatter.ofPattern("HH:mm",I18n.locale(c))):I18n.tr(c,"アラームなし"));r.setTextViewText(R.id.today_streak,"🔥 "+StreakTracker.displayCurrent(c)+I18n.tr(c,"日"));r.setOnClickPendingIntent(R.id.widget_root,WidgetSuite.open(c,MainActivity.class,null,null,31000+id));m.updateAppWidget(id,r);}public void onUpdate(Context c,AppWidgetManager m,int[] ids){for(int id:ids)update(c,m,id);}public void onAppWidgetOptionsChanged(Context c,AppWidgetManager m,int id,android.os.Bundle b){update(c,m,id);}}
